Definition mk_1RB0RC_1LA1LD_1RA0LD_1LB1RC (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_1RB0RC_1LA1LD_1RA0LD_1LB1RC.

(** 1RB0RC_1LA1LD_1RA0LD_1LB1RC *)
(** 1RB0RC_1LA1LD_1RA0LD_1LB1RC -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB0RC_1LA1LD_1RA0LD_1LB1RC : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DR StC
  | StB, S0 => mk S1 DL StA | StB, S1 => mk S1 DL StD
  | StC, S0 => mk S1 DR StA | StC, S1 => mk S0 DL StD
  | StD, S0 => mk S1 DL StB | StD, S1 => mk S1 DR StC end.

(** Its mirror 1LB0LC_1RA1RD_1LA0RD_1RB1LC: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB0RC_1LA1LD_1RA0LD_1LB1RC : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S0 DL StC
  | StB, S0 => mk S1 DR StA | StB, S1 => mk S1 DR StD
  | StC, S0 => mk S1 DL StA | StC, S1 => mk S0 DR StD
  | StD, S0 => mk S1 DR StB | StD, S1 => mk S1 DL StC end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB0RC_1LA1LD_1RA0LD_1LB1RC : list Instr := [].
Definition tmw_1RB0RC_1LA1LD_1RA0LD_1LB1RC : TM := tm_wrap_trs tmm_1RB0RC_1LA1LD_1RA0LD_1LB1RC pins_1RB0RC_1LA1LD_1RA0LD_1LB1RC.
Local Notation tm := tmw_1RB0RC_1LA1LD_1RA0LD_1LB1RC.

Lemma mirror_ok_1RB0RC_1LA1LD_1RA0LD_1LB1RC : mirror_tm tm_1RB0RC_1LA1LD_1RA0LD_1LB1RC = tmm_1RB0RC_1LA1LD_1RA0LD_1LB1RC.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_1RB0RC_1LA1LD_1RA0LD_1LB1RC (p : positive) : cconf := (StC, (Jp p ++ [S0], S0, [S1])).
Local Notation Cc := Cc_1RB0RC_1LA1LD_1RA0LD_1LB1RC.

(** ** The certificate *)

Definition A0_1RB0RC_1LA1LD_1RA0LD_1LB1RC : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S1] [] 0 0 []).
Definition A1_1RB0RC_1LA1LD_1RA0LD_1LB1RC : sconf := mkC StC (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [S1] [] 0 0 []).
Definition chi_1RB0RC_1LA1LD_1RA0LD_1LB1RC : list lstep := [SCycL 2 0; SWin 4; SCycR 2; SWin 4].

Lemma run_int_1RB0RC_1LA1LD_1RA0LD_1LB1RC : srun tm false true chi_1RB0RC_1LA1LD_1RA0LD_1LB1RC A0_1RB0RC_1LA1LD_1RA0LD_1LB1RC = Some (A1_1RB0RC_1LA1LD_1RA0LD_1LB1RC, 4, 8).
Proof. vm_compute. reflexivity. Qed.

Definition B0_1RB0RC_1LA1LD_1RA0LD_1LB1RC : sconf := mkC StC (mkS [] [S1;S0] 1 0 [S1;S0]) S0 (mkS [S1] [] 0 0 []).
Definition B1_1RB0RC_1LA1LD_1RA0LD_1LB1RC : sconf := mkC StC (mkS [] [S1;S1] 1 1 [S1;S0]) S0 (mkS [S1] [] 0 0 []).
Definition cho_1RB0RC_1LA1LD_1RA0LD_1LB1RC : list lstep := [SCycL 2 0; SWin 2; SWinL 8; SCycR 2; SWin 4; SRotL 2; SFoldL 1].

Lemma run_ovf_1RB0RC_1LA1LD_1RA0LD_1LB1RC : srun tm true true cho_1RB0RC_1LA1LD_1RA0LD_1LB1RC B0_1RB0RC_1LA1LD_1RA0LD_1LB1RC = Some (B1_1RB0RC_1LA1LD_1RA0LD_1LB1RC, 4, 14).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB0RC_1LA1LD_1RA0LD_1LB1RC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0]) [] j A0_1RB0RC_1LA1LD_1RA0LD_1LB1RC.
Proof.
  intros p j q0 E. destruct (JpCounter.cview_some_J p j q0 E) as (H1 & _).
  unfold Cc_1RB0RC_1LA1LD_1RA0LD_1LB1RC, cden, A0_1RB0RC_1LA1LD_1RA0LD_1LB1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gei_1RB0RC_1LA1LD_1RA0LD_1LB1RC : forall p j q0, cview p = (j, Some q0) ->
  cden (Jp q0 ++ [S0]) [] j A1_1RB0RC_1LA1LD_1RA0LD_1LB1RC = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (JpCounter.cview_some_J p j q0 E) as (_ & H2).
  unfold Cc_1RB0RC_1LA1LD_1RA0LD_1LB1RC, cden, A1_1RB0RC_1LA1LD_1RA0LD_1LB1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB0RC_1LA1LD_1RA0LD_1LB1RC : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. exists (4 * j + 8). split; [lia|].
  rewrite (gsi_1RB0RC_1LA1LD_1RA0LD_1LB1RC p j q0 E).
  rewrite (srun_sound tm false true chi_1RB0RC_1LA1LD_1RA0LD_1LB1RC A0_1RB0RC_1LA1LD_1RA0LD_1LB1RC A1_1RB0RC_1LA1LD_1RA0LD_1LB1RC 4 8
             run_int_1RB0RC_1LA1LD_1RA0LD_1LB1RC (Jp q0 ++ [S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_1RB0RC_1LA1LD_1RA0LD_1LB1RC p j q0 E).
Qed.

Lemma gso_1RB0RC_1LA1LD_1RA0LD_1LB1RC : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB0RC_1LA1LD_1RA0LD_1LB1RC.
Proof.
  intros p j E. destruct (JpCounter.cview_none_J p j E) as (H1 & _).
  unfold Cc_1RB0RC_1LA1LD_1RA0LD_1LB1RC, cden, B0_1RB0RC_1LA1LD_1RA0LD_1LB1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB0RC_1LA1LD_1RA0LD_1LB1RC : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB0RC_1LA1LD_1RA0LD_1LB1RC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0RC_1LA1LD_1RA0LD_1LB1RC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (JpCounter.cview_none_J p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB0RC_1LA1LD_1RA0LD_1LB1RC
             = (StC, (rep [S1;S1] (S j) ++ [S1;S0], S0, [S1]))).
  { unfold cden, B1_1RB0RC_1LA1LD_1RA0LD_1LB1RC, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StC, (rep [S1;S1] (S j) ++ [S1;S0], S0, [S1]))).
  { unfold Cc_1RB0RC_1LA1LD_1RA0LD_1LB1RC. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_1RB0RC_1LA1LD_1RA0LD_1LB1RC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0RC_1LA1LD_1RA0LD_1LB1RC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0RC_1LA1LD_1RA0LD_1LB1RC B0_1RB0RC_1LA1LD_1RA0LD_1LB1RC B1_1RB0RC_1LA1LD_1RA0LD_1LB1RC 4 14 p j' [] []).
    + exact run_ovf_1RB0RC_1LA1LD_1RA0LD_1LB1RC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0RC_1LA1LD_1RA0LD_1LB1RC p j' E).
    + exact (geo_1RB0RC_1LA1LD_1RA0LD_1LB1RC p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0RC_1LA1LD_1RA0LD_1LB1RC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 11.
  assert (H : match csteps tm 11 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 11 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0RC_1LA1LD_1RA0LD_1LB1RC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0RC_1LA1LD_1RA0LD_1LB1RC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0RC_1LA1LD_1RA0LD_1LB1RC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0RC_1LA1LD_1RA0LD_1LB1RC p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0RC_1LA1LD_1RA0LD_1LB1RC : forall t, ~ In t pins_1RB0RC_1LA1LD_1RA0LD_1LB1RC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB0RC_1LA1LD_1RA0LD_1LB1RC.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB0RC_1LA1LD_1RA0LD_1LB1RC
      with (l := [SCycL 2 0; SWin 2; SWinL 1]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB0RC_1LA1LD_1RA0LD_1LB1RC
      with (l := [SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB0RC_1LA1LD_1RA0LD_1LB1RC
      with (l := [SCycL 2 0; SWin 2; SWinL 2]).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB0RC_1LA1LD_1RA0LD_1LB1RC
      with (l := [SCycL 2 0; SWin 2; SWinL 6]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB0RC_1LA1LD_1RA0LD_1LB1RC
      with (l := []).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0RC_1LA1LD_1RA0LD_1LB1RC
      with (l := [SCycL 2 0; SWin 2; SWinL 4]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB0RC_1LA1LD_1RA0LD_1LB1RC
      with (l := [SCycL 2 0; SWin 2; SWinL 5]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0RC_1LA1LD_1RA0LD_1LB1RC
      with (l := [SCycL 2 0; SWin 2; SWinL 8; SCycR 2; SWin 1]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtrm_1RB0RC_1LA1LD_1RA0LD_1LB1RC : NeverQuasiHaltsTr tmm_1RB0RC_1LA1LD_1RA0LD_1LB1RC.
Proof.
  apply (glue_neverqhtr tmm_1RB0RC_1LA1LD_1RA0LD_1LB1RC pins_1RB0RC_1LA1LD_1RA0LD_1LB1RC Cc 1).
  - exact boot_1RB0RC_1LA1LD_1RA0LD_1LB1RC.
  - intros p _. apply lap_1RB0RC_1LA1LD_1RA0LD_1LB1RC.
  - intros t Ht p _. apply fire_1RB0RC_1LA1LD_1RA0LD_1LB1RC. exact Ht.
Qed.

Theorem nqhtr_1RB0RC_1LA1LD_1RA0LD_1LB1RC : NeverQuasiHaltsTr tm_1RB0RC_1LA1LD_1RA0LD_1LB1RC.
Proof. apply (neverqhtr_mirror tm_1RB0RC_1LA1LD_1RA0LD_1LB1RC). rewrite mirror_ok_1RB0RC_1LA1LD_1RA0LD_1LB1RC. exact nqhtrm_1RB0RC_1LA1LD_1RA0LD_1LB1RC. Qed.

Theorem nonhalt_1RB0RC_1LA1LD_1RA0LD_1LB1RC : NonHalt tm_1RB0RC_1LA1LD_1RA0LD_1LB1RC.
Proof. apply never_qh_tr_nonhalt, nqhtr_1RB0RC_1LA1LD_1RA0LD_1LB1RC. Qed.

End LAPT_1RB0RC_1LA1LD_1RA0LD_1LB1RC.

