(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB0RC_1LA1RC_0LC1LD_1LB0RB : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Bp q0 ++ [S0]) [] j A0_1RB0RC_1LA1RC_0LC1LD_1LB0RB.
