(** The lap ends on [S1;S0] where the anchor has [S1] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_1RB0RC_1LA1RC_0LC1LD_1LB0RB : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Bp q0 ++ [S0]) [] j A1_1RB0RC_1LA1RC_0LC1LD_1LB0RB) = lift (Cc (Pos.succ p)).
Proof.
