(** ** The lap *)

Lemma lap_1RB0RC_1LC0LD_0RA0LD_0LB1RC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
