  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0RC_1LC0LD_0RA0LD_0LB1RC p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0RC_1LC0LD_0RA0LD_0LB1RC B0_1RB0RC_1LC0LD_0RA0LD_0LB1RC B1_1RB0RC_1LC0LD_0RA0LD_0LB1RC 6 14 p j' [] []).
    + exact run_ovf_1RB0RC_1LC0LD_0RA0LD_0LB1RC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0RC_1LC0LD_0RA0LD_0LB1RC p j' E).
    + exact (geo_1RB0RC_1LC0LD_0RA0LD_0LB1RC p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0RC_1LC0LD_0RA0LD_0LB1RC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 8.
  assert (H : match csteps tm 8 c0 with
