  unfold Cc_1RB0RC_1LC1RA_0RA0LD_0LB0LD, cden, P0_1RB0RC_1LC1RA_0RA0LD_0LB0LD, P1_1RB0RC_1LC1RA_0RA0LD_0LB0LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - cbn [rep app Nat.mul Nat.add]; rewrite ?app_nil_r.
    change ([S0;S0;S0]) with (((([]) ++ [S0]) ++ [S0]) ++ [S0]).
    rewrite !lift_app_blank.
    rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB0RC_1LC1RA_0RA0LD_0LB0LD : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB0RC_1LC1RA_0RA0LD_0LB0LD p q0 E) as (HA & HB).
    exists (0 * 0 + 8), (cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0 Z1_1RB0RC_1LC1RA_0RA0LD_0LB0LD).
    split; [lia|]. split; [| exact HB].
    rewrite HA.
    exact (srun_sound tm false true chz_1RB0RC_1LC1RA_0RA0LD_0LB0LD Z0_1RB0RC_1LC1RA_0RA0LD_0LB0LD Z1_1RB0RC_1LC1RA_0RA0LD_0LB0LD 0 8
             run_z_1RB0RC_1LC1RA_0RA0LD_0LB0LD (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0
             ltac:(discriminate) ltac:(reflexivity)).
  - destruct (gp_1RB0RC_1LC1RA_0RA0LD_0LB0LD p j' q0 E) as (HA & HB).
    exists (4 * j' + 12), (cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] j' P1_1RB0RC_1LC1RA_0RA0LD_0LB0LD).
    split; [lia|]. split; [| exact HB].
    rewrite HA.
    exact (srun_sound tm false true chp_1RB0RC_1LC1RA_0RA0LD_0LB0LD P0_1RB0RC_1LC1RA_0RA0LD_0LB0LD P1_1RB0RC_1LC1RA_0RA0LD_0LB0LD 4 12
             run_p_1RB0RC_1LC1RA_0RA0LD_0LB0LD (Ap_Alph_00_10_1 q0 ++ [S0]) [] j'
             ltac:(discriminate) ltac:(reflexivity)).
Qed.

