Lemma geo_1RB0RC_1LC1RA_0RA0LD_0LB0LD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0RC_1LC1RA_0RA0LD_0LB0LD) = lift (Cc (Pos.succ p)).
