    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0RC_1LC1RA_0RA0LD_0LB0LD B0_1RB0RC_1LC1RA_0RA0LD_0LB0LD B1_1RB0RC_1LC1RA_0RA0LD_0LB0LD 4 12 p j' [] []).
    + exact run_ovf_1RB0RC_1LC1RA_0RA0LD_0LB0LD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0RC_1LC1RA_0RA0LD_0LB0LD p j' E).
    + exact (geo_1RB0RC_1LC1RA_0RA0LD_0LB0LD p j' E).
    + lia.
