(** ** The lap *)

Lemma lap_1RB0RC_1LC1RC_1RA0LD_0RC1LB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0RC_1LC1RC_1RA0LD_0RC1LB p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0RC_1LC1RC_1RA0LD_0RC1LB B0_1RB0RC_1LC1RC_1RA0LD_0RC1LB B1_1RB0RC_1LC1RC_1RA0LD_0RC1LB 12 24 p j' [] []).
    + exact run_ovf_1RB0RC_1LC1RC_1RA0LD_0RC1LB.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0RC_1LC1RC_1RA0LD_0RC1LB p j' E).
    + exact (geo_1RB0RC_1LC1RC_1RA0LD_0RC1LB p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0RC_1LC1RC_1RA0LD_0RC1LB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
