Lemma geo_1RB0RC_1LC1RD_0LB1LA_1LB0RD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0RC_1LC1RD_0LB1LA_1LB0RD) = lift (Cc (Pos.succ p)).
