  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB0RC_1LC1RD_0LB1LA_1LB0RD : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB0RC_1LC1RD_0LB1LA_1LB0RD p (pow2 j)).
  - exists (4 * j + 9), (cden [] [] j BB1_1RB0RC_1LC1RD_0LB1LA_1LB0RD).
    split; [lia|]. split; [| exact (gbo_1RB0RC_1LC1RD_0LB1LA_1LB0RD j)].
    rewrite (gso_1RB0RC_1LC1RD_0LB1LA_1LB0RD p j E).
    exact (srun_sound tm true true chb_1RB0RC_1LC1RD_0LB1LA_1LB0RD B0_1RB0RC_1LC1RD_0LB1LA_1LB0RD BB1_1RB0RC_1LC1RD_0LB1LA_1LB0RD 4 9
             run_boot_1RB0RC_1LC1RD_0LB1LA_1LB0RD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 23), (cden [] [] j B1_1RB0RC_1LC1RD_0LB1LA_1LB0RD).
    split; [| exact (geo_1RB0RC_1LC1RD_0LB1LA_1LB0RD p j E)].
    rewrite (gxi_1RB0RC_1LC1RD_0LB1LA_1LB0RD j).
    exact (srun_sound tm true true che_1RB0RC_1LC1RD_0LB1LA_1LB0RD BE0_1RB0RC_1LC1RD_0LB1LA_1LB0RD B1_1RB0RC_1LC1RD_0LB1LA_1LB0RD 4 23
             run_exit_1RB0RC_1LC1RD_0LB1LA_1LB0RD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB0RC_1LC1RD_0LB1LA_1LB0RD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
