    apply (lap_of_run tm Cc true true cho_1RB0RC_1RC0RB_0LC1LD_1LA0LB B0_1RB0RC_1RC0RB_0LC1LD_1LA0LB B1_1RB0RC_1RC0RB_0LC1LD_1LA0LB 4 14 p j' [] []).
