  | StD, S0 => mk S0 DL StB | StD, S1 => mk S0 DR StC end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB0RC_1RC1LB_0LD1RA_0LB0RC : list Instr := [].
Definition tmw_1RB0RC_1RC1LB_0LD1RA_0LB0RC : TM := tm_wrap_trs tm_1RB0RC_1RC1LB_0LD1RA_0LB0RC pins_1RB0RC_1RC1LB_0LD1RA_0LB0RC.
Local Notation tm := tmw_1RB0RC_1RC1LB_0LD1RA_0LB0RC.

Definition Cc_1RB0RC_1RC1LB_0LD1RA_0LB0RC (p : positive) : cconf := (StB, (Ap_Alph_10_11_11 p ++ [S0], S0, [S1;S1])).
Local Notation Cc := Cc_1RB0RC_1RC1LB_0LD1RA_0LB0RC.

(** ** The certificate *)

Definition A0_1RB0RC_1RC1LB_0LD1RA_0LB0RC : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [S1;S1] [] 0 0 []).
Definition A1_1RB0RC_1RC1LB_0LD1RA_0LB0RC : sconf := mkC StB (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S1;S1;S0;S0] [] 0 0 []).
Definition chi_1RB0RC_1RC1LB_0LD1RA_0LB0RC : list lstep := [SWin 2; SWinR 4; SCycL 2 0; SWin 4; SCycR 2; SWin 3; SWinR 7].

Lemma run_int_1RB0RC_1RC1LB_0LD1RA_0LB0RC : srun tm false true chi_1RB0RC_1RC1LB_0LD1RA_0LB0RC A0_1RB0RC_1RC1LB_0LD1RA_0LB0RC = Some (A1_1RB0RC_1RC1LB_0LD1RA_0LB0RC, 4, 20).
Proof. vm_compute. reflexivity. Qed.

Definition B0_1RB0RC_1RC1LB_0LD1RA_0LB0RC : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S1;S0]) S0 (mkS [S1;S1] [] 0 0 []).
Definition B1_1RB0RC_1RC1LB_0LD1RA_0LB0RC : sconf := mkC StB (mkS [] [S1;S0] 1 1 [S1;S1]) S0 (mkS [S1;S1;S0;S0] [] 0 0 []).
(** ** The INNER anchor family -- Ip at StB *)
Definition Cin_1RB0RC_1RC1LB_0LD1RA_0LB0RC (v : positive) : cconf := (StB, (Ip v ++ [S1], S0, [S1])).
Local Notation Cin := Cin_1RB0RC_1RC1LB_0LD1RA_0LB0RC.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_1RB0RC_1RC1LB_0LD1RA_0LB0RC : forall n, Ip (pow2 n) = rep [S1;S0] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_1RB0RC_1RC1LB_0LD1RA_0LB0RC : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [S1] [] 0 0 []).
Definition AI1_1RB0RC_1RC1LB_0LD1RA_0LB0RC : sconf := mkC StB (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S1;S0;S0;S0] [] 0 0 []).
Definition chn_1RB0RC_1RC1LB_0LD1RA_0LB0RC : list lstep := [SWin 1; SWinR 9; SCycL 2 0; SWin 4; SCycR 2; SWin 6].

Lemma run_inner_1RB0RC_1RC1LB_0LD1RA_0LB0RC : srun tm false true chn_1RB0RC_1RC1LB_0LD1RA_0LB0RC AI0_1RB0RC_1RC1LB_0LD1RA_0LB0RC = Some (AI1_1RB0RC_1RC1LB_0LD1RA_0LB0RC, 4, 20).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_1RB0RC_1RC1LB_0LD1RA_0LB0RC : sconf := mkC StB (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S1;S0;S0;S0] [] 0 0 []).
Definition chb_1RB0RC_1RC1LB_0LD1RA_0LB0RC : list lstep := [SWin 2; SWinR 4; SCycL 2 0; SWin 6; SCycR 2; SWin 4; SRotL 1; SWin 1].

Lemma run_boot_1RB0RC_1RC1LB_0LD1RA_0LB0RC : srun tm true true chb_1RB0RC_1RC1LB_0LD1RA_0LB0RC B0_1RB0RC_1RC1LB_0LD1RA_0LB0RC = Some (BB1_1RB0RC_1RC1LB_0LD1RA_0LB0RC, 4, 17).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB0RC_1RC1LB_0LD1RA_0LB0RC : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S1]) S0 (mkS [S1] [] 0 0 []).
Definition che_1RB0RC_1RC1LB_0LD1RA_0LB0RC : list lstep := [SWin 1; SWinR 9; SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWin 4; SWinR 7; SRotL 1; SFoldL 1].

Lemma run_exit_1RB0RC_1RC1LB_0LD1RA_0LB0RC : srun tm true true che_1RB0RC_1RC1LB_0LD1RA_0LB0RC BE0_1RB0RC_1RC1LB_0LD1RA_0LB0RC = Some (B1_1RB0RC_1RC1LB_0LD1RA_0LB0RC, 4, 27).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB0RC_1RC1LB_0LD1RA_0LB0RC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A0_1RB0RC_1RC1LB_0LD1RA_0LB0RC.
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p j q0 E) as (H1 & _).
  unfold Cc_1RB0RC_1RC1LB_0LD1RA_0LB0RC, cden, A0_1RB0RC_1RC1LB_0LD1RA_0LB0RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S1;S1;S0;S0] where the anchor has [S1;S1] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_1RB0RC_1RC1LB_0LD1RA_0LB0RC : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A1_1RB0RC_1RC1LB_0LD1RA_0LB0RC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p j q0 E) as (_ & H2).
  unfold Cc_1RB0RC_1RC1LB_0LD1RA_0LB0RC, cden, A1_1RB0RC_1RC1LB_0LD1RA_0LB0RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S1;S1;S0;S0]) with ((([S1;S1]) ++ [S0]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB0RC_1RC1LB_0LD1RA_0LB0RC : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E.
  exists (4 * j + 20), (cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A1_1RB0RC_1RC1LB_0LD1RA_0LB0RC).
  split; [lia|]. split; [| exact (gei_1RB0RC_1RC1LB_0LD1RA_0LB0RC p j q0 E)].
  rewrite (gsi_1RB0RC_1RC1LB_0LD1RA_0LB0RC p j q0 E).
  exact (srun_sound tm false true chi_1RB0RC_1RC1LB_0LD1RA_0LB0RC A0_1RB0RC_1RC1LB_0LD1RA_0LB0RC A1_1RB0RC_1RC1LB_0LD1RA_0LB0RC 4 20
           run_int_1RB0RC_1RC1LB_0LD1RA_0LB0RC (Ap_Alph_10_11_11 q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_1RB0RC_1RC1LB_0LD1RA_0LB0RC : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB0RC_1RC1LB_0LD1RA_0LB0RC.
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (H1 & _).
  unfold Cc_1RB0RC_1RC1LB_0LD1RA_0LB0RC, cden, B0_1RB0RC_1RC1LB_0LD1RA_0LB0RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB0RC_1RC1LB_0LD1RA_0LB0RC : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB0RC_1RC1LB_0LD1RA_0LB0RC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0RC_1RC1LB_0LD1RA_0LB0RC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB0RC_1RC1LB_0LD1RA_0LB0RC
             = (StB, (rep [S1;S0] (S j) ++ [S1;S1], S0, (([S1;S1]) ++ [S0]) ++ [S0]))).
  { unfold cden, B1_1RB0RC_1RC1LB_0LD1RA_0LB0RC, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StB, ((rep [S1;S0] (S j) ++ [S1;S1]) ++ [S0], S0, [S1;S1]))).
  { unfold Cc_1RB0RC_1RC1LB_0LD1RA_0LB0RC. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lift_app_blank. rewrite !lbl_1RB0RC_1RC1LB_0LD1RA_0LB0RC. reflexivity.
Qed.

Lemma gsn_1RB0RC_1RC1LB_0LD1RA_0LB0RC : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ip q0 ++ [S1]) [] i AI0_1RB0RC_1RC1LB_0LD1RA_0LB0RC.
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (H1 & _).
  unfold Cin_1RB0RC_1RC1LB_0LD1RA_0LB0RC, cden, AI0_1RB0RC_1RC1LB_0LD1RA_0LB0RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_1RB0RC_1RC1LB_0LD1RA_0LB0RC : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S1]) [] i AI1_1RB0RC_1RC1LB_0LD1RA_0LB0RC) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (_ & H2).
  unfold Cin_1RB0RC_1RC1LB_0LD1RA_0LB0RC, cden, AI1_1RB0RC_1RC1LB_0LD1RA_0LB0RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S1;S0;S0;S0]) with (((([S1]) ++ [S0]) ++ [S0]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_1RB0RC_1RC1LB_0LD1RA_0LB0RC : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 20), (cden (Ip q0 ++ [S1]) [] i AI1_1RB0RC_1RC1LB_0LD1RA_0LB0RC).
  split; [lia|]. split; [| exact (gen_1RB0RC_1RC1LB_0LD1RA_0LB0RC v i q0 E)].
  rewrite (gsn_1RB0RC_1RC1LB_0LD1RA_0LB0RC v i q0 E).
  exact (srun_sound tm false true chn_1RB0RC_1RC1LB_0LD1RA_0LB0RC AI0_1RB0RC_1RC1LB_0LD1RA_0LB0RC AI1_1RB0RC_1RC1LB_0LD1RA_0LB0RC 4 20
           run_inner_1RB0RC_1RC1LB_0LD1RA_0LB0RC (Ip q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/3
    trailing blanks. *)
Lemma gbo_1RB0RC_1RC1LB_0LD1RA_0LB0RC : forall j, lift (cden [] [] j BB1_1RB0RC_1RC1LB_0LD1RA_0LB0RC) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB0RC_1RC1LB_0LD1RA_0LB0RC = (StB, (rep [S1;S0] j ++ [S1;S1], S0, ((([S1]) ++ [S0]) ++ [S0]) ++ [S0]))).
  { unfold cden, BB1_1RB0RC_1RC1LB_0LD1RA_0LB0RC, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StB, (rep [S1;S0] j ++ [S1;S1], S0, [S1]))).
  { unfold Cin_1RB0RC_1RC1LB_0LD1RA_0LB0RC. rewrite epow2_1RB0RC_1RC1LB_0LD1RA_0LB0RC.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB0RC_1RC1LB_0LD1RA_0LB0RC. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB0RC_1RC1LB_0LD1RA_0LB0RC : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_1RB0RC_1RC1LB_0LD1RA_0LB0RC.
Proof.
  intro j.
  destruct (ILCounter.cview_none_I (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB0RC_1RC1LB_0LD1RA_0LB0RC, cden, BE0_1RB0RC_1RC1LB_0LD1RA_0LB0RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB0RC_1RC1LB_0LD1RA_0LB0RC : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. exact lapi_1RB0RC_1RC1LB_0LD1RA_0LB0RC. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB0RC_1RC1LB_0LD1RA_0LB0RC : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB0RC_1RC1LB_0LD1RA_0LB0RC p (pow2 j)).
  - exists (4 * j + 17), (cden [] [] j BB1_1RB0RC_1RC1LB_0LD1RA_0LB0RC).
    split; [lia|]. split; [| exact (gbo_1RB0RC_1RC1LB_0LD1RA_0LB0RC j)].
    rewrite (gso_1RB0RC_1RC1LB_0LD1RA_0LB0RC p j E).
    exact (srun_sound tm true true chb_1RB0RC_1RC1LB_0LD1RA_0LB0RC B0_1RB0RC_1RC1LB_0LD1RA_0LB0RC BB1_1RB0RC_1RC1LB_0LD1RA_0LB0RC 4 17
             run_boot_1RB0RC_1RC1LB_0LD1RA_0LB0RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 27), (cden [] [] j B1_1RB0RC_1RC1LB_0LD1RA_0LB0RC).
    split; [| exact (geo_1RB0RC_1RC1LB_0LD1RA_0LB0RC p j E)].
    rewrite (gxi_1RB0RC_1RC1LB_0LD1RA_0LB0RC j).
    exact (srun_sound tm true true che_1RB0RC_1RC1LB_0LD1RA_0LB0RC BE0_1RB0RC_1RC1LB_0LD1RA_0LB0RC B1_1RB0RC_1RC1LB_0LD1RA_0LB0RC 4 27
             run_exit_1RB0RC_1RC1LB_0LD1RA_0LB0RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB0RC_1RC1LB_0LD1RA_0LB0RC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0RC_1RC1LB_0LD1RA_0LB0RC p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB0RC_1RC1LB_0LD1RA_0LB0RC p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0RC_1RC1LB_0LD1RA_0LB0RC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 30.
  assert (H : match csteps tm 30 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 30 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0RC_1RC1LB_0LD1RA_0LB0RC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0RC_1RC1LB_0LD1RA_0LB0RC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0RC_1RC1LB_0LD1RA_0LB0RC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0RC_1RC1LB_0LD1RA_0LB0RC p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0RC_1RC1LB_0LD1RA_0LB0RC : forall t, ~ In t pins_1RB0RC_1RC1LB_0LD1RA_0LB0RC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB0RC_1RC1LB_0LD1RA_0LB0RC.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RC_1RC1LB_0LD1RA_0LB0RC [SWin 2; SWinR 4; SCycL 2 0; SWin 6; SCycR 2; SWin 4; SRotL 1; SWin 1; SWin 2] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
