Lemma lapi_1RB0RD_0LB0LC_1RD1LC_1RB1RA : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
