Lemma geo_1RB0RD_0LB0LC_1RD1LC_1RB1RA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0RD_0LB0LC_1RD1LC_1RB1RA) = lift (Cc (Pos.succ p)).
