Lemma fireo_1RB0RD_0LB0LC_1RD1LC_1RB1RA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0RD_0LB0LC_1RD1LC_1RB1RA = Some t ->
