(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB0RD_0LC0RA_1RA1LC_0LC0LC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_110_111_111 q0 ++ [S0]) [] j A0_1RB0RD_0LC0RA_1RA1LC_0LC0LC.
