(** ** The lap *)

Lemma lap_1RB0RD_0LC0RA_1RA1LC_0LC0LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
