    apply (lap_of_run tm Cc true true cho_1RB0RD_0LC0RA_1RA1LC_0LC0LC B0_1RB0RD_0LC0RA_1RA1LC_0LC0LC B1_1RB0RD_0LC0RA_1RA1LC_0LC0LC 8 26 p j' [] []).
    + exact run_ovf_1RB0RD_0LC0RA_1RA1LC_0LC0LC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0RD_0LC0RA_1RA1LC_0LC0LC p j' E).
    + exact (geo_1RB0RD_0LC0RA_1RA1LC_0LC0LC p j' E).
    + lia.
