Lemma lbl_1RB0RD_0LC0RB_1LA1LC_1LC1LD : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB0RD_0LC0RB_1LA1LC_1LC1LD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0RD_0LC0RB_1LA1LC_1LC1LD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_00_01_0.cview_none_Alph_00_01_0 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB0RD_0LC0RB_1LA1LC_1LC1LD
             = (StB, (rep [S0;S0] (S j) ++ [S0;S0;S1], S0, []))).
