Lemma gen_1RB0RD_0LC0RB_1LA1LC_1LC1LD : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ap_Alph_00_01_0 q0 ++ [S1;S1]) [] i AI1_1RB0RD_0LC0RB_1LA1LC_1LC1LD) = lift (Cin (Pos.succ v)).
