Lemma lapin_1RB0RD_0LC0RB_1LA1LC_1LC1LD : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (6 * i + 4), (cden (Ap_Alph_00_01_0 q0 ++ [S1;S1]) [] i AI1_1RB0RD_0LC0RB_1LA1LC_1LC1LD).
  split; [lia|]. split; [| exact (gen_1RB0RD_0LC0RB_1LA1LC_1LC1LD v i q0 E)].
