(** ** The lap *)

Lemma lap_1RB0RD_0LC1RA_1RD1LC_0LA1RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
