Lemma fireo_1RB0RD_0LC1RA_1RD1LC_0LA1RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0RD_0LC1RA_1RD1LC_0LA1RB = Some t ->
