    apply (lap_of_run tm Cc true true cho_1RB0RD_0LC1RC_1LD0RB_1LA1LD B0_1RB0RD_0LC1RC_1LD0RB_1LA1LD B1_1RB0RD_0LC1RC_1LD0RB_1LA1LD 8 15 p j' [] []).
    + exact run_ovf_1RB0RD_0LC1RC_1LD0RB_1LA1LD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0RD_0LC1RC_1LD0RB_1LA1LD p j' E).
    + exact (geo_1RB0RD_0LC1RC_1LD0RB_1LA1LD p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB0RD_0LC1RC_1LD0RB_1LA1LD : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 22.
