Lemma gsi_1RB0RD_0LC1RD_1RB1LC_0LA0RB : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A0_1RB0RD_0LC1RD_1RB1LC_0LA0RB.
