Lemma gsi_1RB0RD_0RC1LB_1LA1RD_1RC0LB : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0]) [] j A0_1RB0RD_0RC1LB_1LA1RD_1RC0LB.
