Lemma gp_1RB0RD_0RC1RB_1LD0RC_0LD1LA : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] j P0_1RB0RD_0RC1RB_1LD0RC_0LD1LA /\
  cden (Kp q0 ++ [S0]) [] j P1_1RB0RD_0RC1RB_1LD0RC_0LD1LA = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (KpCounter.cview_some_K p (S j) q0 E) as (H1 & H2).
  unfold Cc_1RB0RD_0RC1RB_1LD0RC_0LD1LA, cden, P0_1RB0RD_0RC1RB_1LD0RC_0LD1LA, P1_1RB0RD_0RC1RB_1LD0RC_0LD1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
