Lemma fire_1RB0RD_1LB1RC_0LD0RB_1LA1LD : forall t, ~ In t pins_1RB0RD_1LB1RC_0LD0RB_1LA1LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
